//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::nat::pow_exponent, nat::pow_small`; the
//! native twin is `benches/native/Bench/NatPowExponent.lean`.
//! Nat words on both sides (2n+1); every result stays below 2^63; the limit test, then the word
//! helper, as a translator's fast path composes them

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::nat;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match nat::pow_exponent(&nat_arg(nat_box((x >> 4) & 15))) {
                Ok(e) => match nat::pow_small(nat_unbox(nat_box(x >> 60)), e as u64) {
                    Some(v) => nat_unbox(nat_box(v)),
                    None => big(),
                },
                Err(p) => end(p),
            },
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
